#!/usr/bin/env bash
# ============================================================================
#  AZ PANEL - self-contained installer
#
#  Installs a Minecraft/VPS game-server management panel to /opt/az-panel
#  (or $AZ_PANEL_DIR). This script embeds the entire application (see the
#  base64 payload appended after the __AZ_PANEL_PAYLOAD__ marker at the
#  bottom of this file) - no separate download or git clone is required.
#
#  Design constraints honored throughout this script:
#    - NEVER uses systemd/systemctl/journalctl for anything. Process
#      persistence is handled by PM2 (a userspace Node process manager) when
#      available, or a bundled nohup+PID-file fallback supervisor otherwise.
#      Optional reboot-persistence uses a plain crontab @reboot entry, never
#      a systemd unit.
#    - The application itself has ZERO external npm runtime dependencies
#      (uses Node's built-in node:sqlite, node:http, node:crypto, and global
#      fetch only), so there is no `npm install` step for the app - this
#      removes the single biggest source of installer failures.
#    - Idempotent: safe to re-run.
# ============================================================================
set -euo pipefail

AZ_PANEL_DIR="${AZ_PANEL_DIR:-/opt/az-panel}"
AZ_PANEL_PORT="${AZ_PANEL_PORT:-6767}"
MIN_NODE_MAJOR=22
SCRIPT_SELF="$(readlink -f "$0" 2>/dev/null || echo "$0")"

c_reset='\033[0m'; c_bold='\033[1m'; c_red='\033[31m'; c_green='\033[32m'; c_yellow='\033[33m'; c_cyan='\033[36m'
log()  { printf "${c_cyan}[az-panel]${c_reset} %s\n" "$1"; }
ok()   { printf "${c_green}[az-panel]${c_reset} %s\n" "$1"; }
warn() { printf "${c_yellow}[az-panel] WARNING:${c_reset} %s\n" "$1"; }
err()  { printf "${c_red}[az-panel] ERROR:${c_reset} %s\n" "$1" >&2; }
die()  { err "$1"; exit 1; }

# ---------------------------------------------------------------------------
# 0. Privilege / platform checks
# ---------------------------------------------------------------------------
if [ "$(id -u)" -ne 0 ]; then
  die "Please run this installer as root (e.g. sudo ./az-panel.sh)."
fi

OS_ID="unknown"
if [ -f /etc/os-release ]; then
  . /etc/os-release
  OS_ID="${ID:-unknown}"
fi

case "$(uname -s)" in
  Linux) : ;;
  *) die "This installer supports Linux only (detected: $(uname -s))." ;;
esac

log "Target directory : $AZ_PANEL_DIR"
log "Target port       : $AZ_PANEL_PORT"
log "Detected OS        : ${PRETTY_NAME:-$OS_ID}"

# ---------------------------------------------------------------------------
# 1. Dependency checks / installation (Node.js, Java). Docker is optional.
# ---------------------------------------------------------------------------
have_cmd() { command -v "$1" >/dev/null 2>&1; }

node_major_version() {
  node -v 2>/dev/null | sed -E 's/^v([0-9]+).*/\1/'
}

install_nodejs() {
  log "Installing Node.js ${MIN_NODE_MAJOR}.x via NodeSource..."
  if have_cmd apt-get; then
    if ! curl -fsSL "https://deb.nodesource.com/setup_${MIN_NODE_MAJOR}.x" -o /tmp/nodesource_setup.sh; then
      die "Could not reach deb.nodesource.com to install Node.js. Install Node.js ${MIN_NODE_MAJOR}+ manually, then re-run this installer."
    fi
    bash /tmp/nodesource_setup.sh
    apt-get install -y nodejs
  elif have_cmd dnf; then
    curl -fsSL "https://rpm.nodesource.com/setup_${MIN_NODE_MAJOR}.x" | bash -
    dnf install -y nodejs
  elif have_cmd yum; then
    curl -fsSL "https://rpm.nodesource.com/setup_${MIN_NODE_MAJOR}.x" | bash -
    yum install -y nodejs
  else
    die "No supported package manager found (apt-get/dnf/yum). Install Node.js ${MIN_NODE_MAJOR}+ manually, then re-run this installer."
  fi
}

if have_cmd node && [ "$(node_major_version)" -ge "$MIN_NODE_MAJOR" ] 2>/dev/null; then
  ok "Node.js $(node -v) already installed."
else
  install_nodejs
  have_cmd node || die "Node.js installation failed."
  ok "Node.js $(node -v) installed."
fi

if have_cmd java; then
  ok "Java already installed: $(java -version 2>&1 | head -n1)"
else
  log "Installing OpenJDK 21 (required to run Minecraft server jars)..."
  if have_cmd apt-get; then
    apt-get update -y && apt-get install -y openjdk-21-jre-headless || apt-get install -y default-jre-headless \
      || warn "Could not install a JRE automatically. Install Java 17+ manually before starting Minecraft servers."
  elif have_cmd dnf; then
    dnf install -y java-21-openjdk-headless || warn "Could not install a JRE automatically. Install Java 17+ manually."
  elif have_cmd yum; then
    yum install -y java-21-openjdk-headless || warn "Could not install a JRE automatically. Install Java 17+ manually."
  else
    warn "No supported package manager found; install Java 17+ manually before starting Minecraft servers."
  fi
fi

if have_cmd docker; then
  ok "Docker detected - the Docker server runtime will be available in the panel."
else
  warn "Docker not found. The panel's 'local process' runtime will still work fully; the optional Docker runtime will be unavailable until Docker is installed."
fi

have_cmd tar || die "The 'tar' command is required (used for backups) but was not found."

# ---------------------------------------------------------------------------
# 2. Extract embedded application payload
# ---------------------------------------------------------------------------
log "Installing AZ PANEL to $AZ_PANEL_DIR ..."
mkdir -p "$AZ_PANEL_DIR"

PAYLOAD_START="$(awk '/^__AZ_PANEL_PAYLOAD__$/{print NR+1; exit 0}' "$SCRIPT_SELF")"
if [ -z "$PAYLOAD_START" ]; then
  die "This script is missing its embedded payload (marker not found). Re-download az-panel.sh."
fi

TMP_TARBALL="$(mktemp /tmp/az-panel-payload.XXXXXX.tar.gz)"
tail -n +"$PAYLOAD_START" "$SCRIPT_SELF" | base64 -d > "$TMP_TARBALL"
tar -xzf "$TMP_TARBALL" -C "$AZ_PANEL_DIR"
rm -f "$TMP_TARBALL"

mkdir -p "$AZ_PANEL_DIR/data" "$AZ_PANEL_DIR/servers" "$AZ_PANEL_DIR/backups"
chmod +x "$AZ_PANEL_DIR/scripts/manage.sh" "$AZ_PANEL_DIR/scripts/create-admin.js" 2>/dev/null || true

ok "Application files extracted."

# ---------------------------------------------------------------------------
# 3. Write runtime configuration (port, etc.)
# ---------------------------------------------------------------------------
CONFIG_FILE="$AZ_PANEL_DIR/data/config.json"
if [ ! -f "$CONFIG_FILE" ]; then
  SESSION_SECRET="$(node -e "console.log(require('crypto').randomBytes(48).toString('hex'))")"
  cat > "$CONFIG_FILE" <<EOF
{
  "sessionSecret": "$SESSION_SECRET",
  "port": $AZ_PANEL_PORT,
  "theme": "crimson",
  "runtime": "local",
  "storageDir": "$AZ_PANEL_DIR/servers",
  "backupDir": "$AZ_PANEL_DIR/backups",
  "env": "production"
}
EOF
  ok "Wrote initial configuration ($CONFIG_FILE)."
else
  log "Existing configuration found - leaving $CONFIG_FILE untouched."
fi

# ---------------------------------------------------------------------------
# 4. Optional non-interactive admin bootstrap
#    (Users can also just visit the panel URL and use the first-run setup
#    screen in the browser - this step is entirely optional.)
# ---------------------------------------------------------------------------
if [ -n "${AZ_ADMIN_USER:-}" ] && [ -n "${AZ_ADMIN_PASS:-}" ]; then
  log "Creating admin account '$AZ_ADMIN_USER' from AZ_ADMIN_USER/AZ_ADMIN_PASS..."
  (cd "$AZ_PANEL_DIR" && AZ_ADMIN_USER="$AZ_ADMIN_USER" AZ_ADMIN_PASS="$AZ_ADMIN_PASS" \
    node --experimental-sqlite scripts/create-admin.js --non-interactive) \
    && ok "Admin account ready." || warn "Admin account creation failed; you can create it from the web setup screen instead."
elif [ -t 0 ]; then
  read -r -p "$(printf '%b' "${c_cyan}[az-panel]${c_reset} Create an admin account now via this terminal? [Y/n] ")" CREATE_NOW
  CREATE_NOW="${CREATE_NOW:-Y}"
  if [[ "$CREATE_NOW" =~ ^[Yy] ]]; then
    (cd "$AZ_PANEL_DIR" && node --experimental-sqlite scripts/create-admin.js) \
      || warn "Admin account creation failed; you can create it from the web setup screen instead."
  else
    log "Skipping - open the panel URL after install and use the first-run setup screen."
  fi
else
  log "Non-interactive shell - skipping CLI admin creation. Use the web setup screen on first visit, or set AZ_ADMIN_USER/AZ_ADMIN_PASS and re-run."
fi

# ---------------------------------------------------------------------------
# 5. Process supervision: PM2 preferred, dependency-free fallback otherwise.
#    Neither path touches systemd/systemctl.
# ---------------------------------------------------------------------------
log "Setting up process supervision..."
cd "$AZ_PANEL_DIR"

USING_PM2=0
if have_cmd pm2; then
  USING_PM2=1
else
  log "Attempting to install PM2 globally via npm (optional; a fallback supervisor is used if this fails)..."
  if npm install -g pm2 >/tmp/az-panel-pm2-install.log 2>&1; then
    USING_PM2=1
  else
    warn "PM2 installation failed (likely no network access). Falling back to the bundled nohup-based supervisor - this is fully supported, just without PM2's extra tooling."
  fi
fi

./scripts/manage.sh stop >/dev/null 2>&1 || true
./scripts/manage.sh start

if [ "$USING_PM2" -eq 1 ] && have_cmd pm2; then
  pm2 save >/dev/null 2>&1 || true
  # Reboot persistence via plain crontab (@reboot), never systemd:
  if have_cmd crontab; then
    CRON_LINE="@reboot $(command -v pm2) resurrect >> $AZ_PANEL_DIR/data/pm2-boot.log 2>&1"
    ( crontab -l 2>/dev/null | grep -vF "pm2 resurrect" ; echo "$CRON_LINE" ) | crontab -
    ok "Added a crontab @reboot entry to resume AZ PANEL after reboots (no systemd used)."
  fi
else
  if have_cmd crontab; then
    CRON_LINE="@reboot $AZ_PANEL_DIR/scripts/manage.sh start >> $AZ_PANEL_DIR/data/az-panel-boot.log 2>&1"
    ( crontab -l 2>/dev/null | grep -vF "$AZ_PANEL_DIR/scripts/manage.sh start" ; echo "$CRON_LINE" ) | crontab -
    ok "Added a crontab @reboot entry to resume AZ PANEL after reboots (no systemd used)."
  fi
fi

# ---------------------------------------------------------------------------
# 6. Health check
# ---------------------------------------------------------------------------
log "Waiting for AZ PANEL to come up on port $AZ_PANEL_PORT..."
HEALTHY=0
for i in $(seq 1 20); do
  if curl -fsS "http://127.0.0.1:${AZ_PANEL_PORT}/health" >/dev/null 2>&1; then
    HEALTHY=1
    break
  fi
  sleep 0.5
done

if [ "$HEALTHY" -eq 1 ]; then
  ok "AZ PANEL is up and healthy."
else
  warn "Could not confirm AZ PANEL is responding on port $AZ_PANEL_PORT yet. Check logs with: $AZ_PANEL_DIR/scripts/manage.sh logs"
fi

SERVER_IP="$(curl -fsS -m 3 https://ifconfig.me 2>/dev/null || hostname -I 2>/dev/null | awk '{print $1}' || echo "<your-server-ip>")"

echo
ok "============================================================"
ok " AZ PANEL installed at: $AZ_PANEL_DIR"
ok " Open:  http://${SERVER_IP}:${AZ_PANEL_PORT}"
ok " Manage: $AZ_PANEL_DIR/scripts/manage.sh {start|stop|restart|status|logs}"
ok " Credits: UI inspired by Jishnu."
ok "============================================================"
exit 0

__AZ_PANEL_PAYLOAD__

